INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('rev-1', 'Executive Director 1', 'المدير التنفيذي 1', 'Al-Jazeera Gulf Holdings W.L.L.', 'مجموعة الجزيرة الخليجية القابضة', 'Working with Qafila Creative streamlined our operations and exceeded delivery expectations.', 'العمل مع قافلة الإبداعية ساهم في رفع كفاءة عملياتنا وتجاوز توقعاتنا في التسليم.', 5, true, 1, 2026, now() - interval '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'qafila-creative-insights-1', 'Qafila Creative Industry Brief #1: Complete Brand Identity System', 'تقرير قافلة الإبداعية التخصصي #1: تصميم نظام الهوية البصرية الكامل', 'Key operational benchmarks and best practices from Qafila Creative in Seef District.', 'أبرز المعايير التشغيلية وأفضل الممارسات من قافلة الإبداعية في Seef District.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Independent brand and digital agency partnering with ambitious regional enterprises on strategy, design systems, and launch campaigns. Our Complete Brand Identity System division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"وكالة مستقلة للعلامات التجارية والتجربة الرقمية تتعاون مع المؤسسات الطموحة في الاستراتيجية والتصميم والحملات. يساعد قسم تصميم نظام الهوية البصرية الكامل المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Independent brand and digital agency partnering with ambitious regional enterprises on strategy, design systems, and launch campaigns.</p><p>Our Complete Brand Identity System division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>وكالة مستقلة للعلامات التجارية والتجربة الرقمية تتعاون مع المؤسسات الطموحة في الاستراتيجية والتصميم والحملات.</p><p>يساعد قسم تصميم نظام الهوية البصرية الكامل المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'agency', '{"agency","Seef District","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '9 days', true, now() - interval '9 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How do we engage Qafila Creative for a new project?', 'كيف يمكننا البدء بمشروع جديد مع قافلة الإبداعية؟', 'Contact Qafila Creative at hello@qafilacreative.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر hello@qafilacreative.bh أو إرسال طلب إلكتروني وسيرد فريق قافلة الإبداعية خلال يوم عمل واحد.', 'general', true, 1, now()) ON CONFLICT (id) DO NOTHING;
